#!/usr/bin/env python3

def identify_repeating_patterns(hex_str, min_len=4, max_len=16):
    patterns = {}
    # Look for patterns of different lengths
    for length in range(min_len, max_len + 1, 2):  # increment by 2 since hex bytes are pairs
        for i in range(0, len(hex_str) - length + 1, 2):
            pattern = hex_str[i:i+length]
            if hex_str.count(pattern) > 1:
                patterns[pattern] = hex_str.count(pattern)

    # Sort by number of occurrences
    return dict(sorted(patterns.items(), key=lambda x: x[1], reverse=True))

def convert_to_ascii(hex_str):
    try:
        # Convert hex to bytes and then to ASCII, ignoring non-printable chars
        bytes_data = bytes.fromhex(hex_str)
        ascii_str = ''.join(chr(b) if 32 <= b <= 126 else '.' for b in bytes_data)
        return ascii_str
    except:
        return None

# Read the cleaned hex
with open('cleaned_hex.txt', 'r') as f:
    hex_data = f.read().strip()

# Print basic statistics
print(f"Total length: {len(hex_data)} hex characters ({len(hex_data)//2} bytes)\n")

# Look for repeating patterns
print("Most common repeating patterns:")
patterns = identify_repeating_patterns(hex_data)
for pattern, count in list(patterns.items())[:10]:
    print(f"Pattern: {pattern} (occurs {count} times)")
    ascii_repr = convert_to_ascii(pattern)
    if ascii_repr:
        print(f"ASCII: {ascii_repr}")
    print()

# Convert full hex to ASCII and look for readable strings
print("\nLooking for ASCII strings in the data:")
ascii_data = convert_to_ascii(hex_data)
if ascii_data:
    # Split into chunks for readability
    chunk_size = 80
    for i in range(0, len(ascii_data), chunk_size):
        chunk = ascii_data[i:i+chunk_size]
        if any(c != '.' for c in chunk):  # Only print chunks with readable characters
            print(chunk)

#!/usr/bin/env python3
import re

def read_hex_data(filename):
    with open(filename, 'r') as f:
        content = f.read()
        hex_data = ''
        for line in content.strip().split('\n'):
            parts = line.split()
            if len(parts) > 1:
                hex_values = parts[1:9]
                hex_data += ''.join(hex_values)
    return bytes.fromhex(hex_data)

def reverse_bits(data):
    result = bytearray()
    for b in data:
        reversed_byte = int('{:08b}'.format(b)[::-1], 2)
        result.append(reversed_byte)
    return bytes(result)

def main():
    # Read and process the data
    data = read_hex_data('ctf_files/hypokrinesthai.txt')
    reversed_data = reverse_bits(data)

    # Try to decode as text
    text = reversed_data.decode('utf-8', errors='ignore')

    # Split into words and analyze
    words = re.findall(r'[a-zA-Z]+', text)

    # Print the full text with word boundaries preserved
    print("Full decoded text:")
    print(text)

    # Look for Latin words and phrases
    print("\nPotential Latin words (length > 4):")
    for word in sorted(set(words)):
        if len(word) > 4:
            print(word)

    # Save the output
    with open('latin_output.txt', 'w') as f:
        f.write(text)

    # Look for anything that might be flag-like
    print("\nChecking for potential flag patterns...")
    flag_pattern = re.compile(r'csawctf\{[^}]*\}')
    matches = flag_pattern.findall(text)
    if matches:
        print("Found potential flags:")
        for match in matches:
            print(match)

    # Try some common Latin endings
    latin_endings = ['us', 'um', 'ae', 'am', 'em', 'orum', 'arum']
    print("\nWords with Latin endings:")
    for word in sorted(set(words)):
        for ending in latin_endings:
            if word.endswith(ending) and len(word) > len(ending):
                print(f"{word} (ends with {ending})")

if __name__ == "__main__":
    main()

