import re
import binascii

with open('/home/ctfplayer/ctf_files/hypokrinesthai.txt', 'r') as f:
    content = f.read()

# Extract hex values
hex_pattern = re.compile(r'([0-9a-f]{2}\s)+')
hex_values = []
for line in content.split('\n'):
    if '|' in line:
        hex_part = line.split('|')[0].strip()
        matches = hex_pattern.findall(hex_part)
        if matches:
            hex_values.extend(matches[0].strip().split())

# Convert hex to bytes
bytes_data = bytes.fromhex(''.join(hex_values))

# Try various transformations
print("Raw bytes decoded as UTF-8:")
try:
    print(bytes_data.decode('utf-8', errors='ignore'))
except:
    print("Failed to decode as UTF-8")

print("\nReversed bytes decoded as UTF-8:")
try:
    print(bytes_data[::-1].decode('utf-8', errors='ignore'))
except:
    print("Failed to decode reversed bytes as UTF-8")

# Look for patterns with 04
print("\nSequences around 04:")
for i in range(len(hex_values)-2):
    if hex_values[i+1] == '04':
        print(f"{hex_values[i]} 04 {hex_values[i+2]}")

# Try ROT13 on ASCII parts
print("\nROT13 of ASCII parts:")
ascii_parts = []
for line in content.split('\n'):
    if '|' in line:
        ascii_part = line.split('|')[1].strip()
        if ascii_part:
            ascii_parts.append(ascii_part)
print(''.join(ascii_parts))

def read_bytes(filename):
    with open(filename, 'rb') as f:
        return f.read()

def extract_hex_values(filename):
    hex_values = []
    with open(filename, 'r') as f:
        for line in f:
            if '|' in line:
                hex_part = line.split('|')[0].strip()
                hex_values.extend([int(x, 16) for x in hex_part.split()])
    return bytes(hex_values)

def try_decode(data):
    # Try 1: Direct decode
    try:
        print("UTF-8 decode:", data.decode('utf-8', errors='ignore'))
    except:
        pass

    # Try 2: XOR each byte with 0x04 (common pattern)
    xored = bytes([b ^ 0x04 for b in data])
    try:
        print("\nXOR with 0x04:", xored.decode('utf-8', errors='ignore'))
    except:
        pass

    # Try 3: Group by 4 bytes and decode
    for i in range(0, len(data)-4, 4):
        chunk = data[i:i+4]
        if all(c < 128 for c in chunk):
            try:
                print(f"4-byte chunk at {i}:", chunk.decode('ascii', errors='ignore'))
            except:
                pass

    # Try 4: Find pattern around 0x04
    pattern_positions = []
    for i in range(len(data)):
        if data[i] == 0x04:
            pattern_positions.append((i, data[max(0,i-4):i], data[i+1:i+5]))

    print("\nPatterns around 0x04:")
    for pos, before, after in pattern_positions[:10]:
        print(f"Position {pos}: Before={bytes(before).hex()} After={bytes(after).hex()}")

# Read the file and process it
data = extract_hex_values('/home/ctfplayer/ctf_files/hypokrinesthai.txt')

# Try all decoding methods
try_decode(data)

# Try reversed data
print("\nTrying reversed data:")
rev_data = data[::-1]
try_decode(rev_data)

# Check for repeating sequences
seq_len = 4
sequences = {}
for i in range(len(data)-seq_len):
    seq = data[i:i+seq_len]
    if seq in sequences:
        sequences[seq] += 1
    else:
        sequences[seq] = 1

print("\nMost common 4-byte sequences:")
for seq, count in sorted(sequences.items(), key=lambda x: x[1], reverse=True)[:10]:
    print(f"{seq.hex()}: {count} times")
